<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '../api'
const list=ref([]),batches=ref([]),loading=ref(false),dialog=ref(false),drawer=ref(false),detail=ref({})
const filters=ref({keyword:'',grade:'',storageLocation:''}),form=ref({id:null,productBatchNo:'',processingBatchId:null,grade:'一级',weightKg:null,stockedAt:'',storageLocation:''})
const grades=['特级','一级','二级'],batchNo=id=>batches.value.find(x=>x.id===id)?.batchNo||`#${id}`
async function load(){loading.value=true;try{list.value=await api.listInventory(filters.value)}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
function open(row){form.value=row?{...row,stockedAt:row.stockedAt?.slice(0,16)}:{id:null,productBatchNo:'',processingBatchId:batches.value[0]?.id,grade:'一级',weightKg:null,stockedAt:'',storageLocation:''};dialog.value=true}
async function save(){try{const data={...form.value,stockedAt:form.value.stockedAt?`${form.value.stockedAt}:00`:null};form.value.id?await api.updateInventory(form.value.id,data):await api.createInventory(data);dialog.value=false;ElMessage.success('成品库存已保存');await load()}catch(e){ElMessage.error(e.message)}}
async function show(id){detail.value=await api.getInventory(id);drawer.value=true}
onMounted(async()=>{batches.value=await api.listBatches();await load()})
</script>
<template><div class="page-card"><div class="toolbar"><div class="filters"><el-input v-model="filters.keyword" clearable placeholder="成品批次" style="width:180px"/><el-select v-model="filters.grade" clearable placeholder="全部等级" style="width:120px"><el-option v-for="x in grades" :key="x" :label="x" :value="x"/></el-select><el-input v-model="filters.storageLocation" clearable placeholder="库位" style="width:120px"/><el-button @click="load">筛选</el-button></div><el-button type="primary" @click="open()">新增库存</el-button></div><el-table :data="list" v-loading="loading" border stripe><el-table-column prop="productBatchNo" label="成品批次"/><el-table-column label="加工批次"><template #default="{row}">{{batchNo(row.processingBatchId)}}</template></el-table-column><el-table-column prop="grade" label="等级" width="90"/><el-table-column prop="weightKg" label="重量(kg)" width="110"/><el-table-column prop="stockedAt" label="入库时间" width="175"/><el-table-column prop="storageLocation" label="库位" width="90"/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row.id)">详情</el-button><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="form.id?'编辑库存':'新增库存'" width="520px"><el-form :model="form" label-width="100px"><el-form-item label="成品批次"><el-input v-model="form.productBatchNo"/></el-form-item><el-form-item label="加工批次"><el-select v-model="form.processingBatchId" style="width:100%"><el-option v-for="x in batches" :key="x.id" :label="x.batchNo" :value="x.id"/></el-select></el-form-item><el-form-item label="等级"><el-select v-model="form.grade" style="width:100%"><el-option v-for="x in grades" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="重量(kg)"><el-input-number v-model="form.weightKg" :min="0.1" :precision="2"/></el-form-item><el-form-item label="入库时间"><el-date-picker v-model="form.stockedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm" style="width:100%"/></el-form-item><el-form-item label="库位"><el-input v-model="form.storageLocation"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-drawer v-model="drawer" title="成品库存详情" size="420px"><dl class="detail-grid"><template v-for="(v,k) in detail" :key="k"><dt>{{k}}</dt><dd>{{v??'-'}}</dd></template></dl></el-drawer></div></template>
